function MyBlockEditor() {
  const [ blocks, updateBlocks ] = useState([]);
  return (
    <BlockEditorProvider
      value={ blocks }
      onInput={ updateBlocks }
      onChange={ persistBlocks }
     >
       <BlockCanvas height="400px" />
     </BlockEditorProvider>
   );
}
